function delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// ✅ ฟังก์ชันหลักที่รอจนกว่า Button 4 จะเป็น 0
async function waitForButtonRelease() {
    let buttonState = global.get("Button_State") || {};

    // ตั้งสถานะเริ่มต้น
    node.status({ fill: "blue", shape: "dot", text: "กำลังรอการกดปุ่ม Free motor" });

    while (buttonState.button4 === false) {
        await delay(200); // รอ 200ms แล้วเช็คใหม่
        buttonState = global.get("Button_State") || {};
    }

    // เมื่อ button4 = 0
    node.status({ fill: "green", shape: "dot", text: "กดปุ่ม Free motor แล้ว" });
}

// ✅ เรียกใช้งาน
return (async () => {
    await waitForButtonRelease();
    return msg; // ส่งต่อ msg เมื่อ button4 = 0
})();

